export function cleanup(){}export function effect(){return cleanup;}export function handler(){}export function reduce(s,a){return s;}export function init(){return 0;}export function subscribe(){return cleanup;}export function getSnapshot(){return 0;}export function action(s,a){return s;}
export function Child(){return <View/>;}const Wrapped=memo(Child);const Forward=forwardRef(function Forwarded(p,r){return <Child/>;});const Lazy=lazy(()=>import('./Lazy'));
